const INCOME_CATEGORIES = ["工资", "奖金", "兼职", "投资收益", "红包", "其他收入"];
const EXPENSE_CATEGORIES = ["餐饮", "交通", "购物", "居住", "水电", "通讯", "医疗", "教育", "娱乐", "人情", "其他支出"];

const state = {
  records: [],
  filterMonth: "",
  pendingDeleteId: null,
  saving: false
};

const el = {
  form: document.querySelector(".entry-form"),
  date: document.getElementById("f-date"),
  category: document.getElementById("f-category"),
  amount: document.getElementById("f-amount"),
  note: document.getElementById("f-note"),
  month: document.getElementById("f-month"),
  formMsg: document.querySelector('[data-role="form-msg"]'),
  list: document.querySelector('[data-role="record-list"]'),
  listHint: document.querySelector('[data-role="list-hint"]'),
  sumIncome: document.querySelector('[data-role="sum-income"]'),
  sumExpense: document.querySelector('[data-role="sum-expense"]'),
  sumBalance: document.querySelector('[data-role="sum-balance"]'),
  resetBtn: document.querySelector('[data-role="reset-form"]'),
  clearMonthBtn: document.querySelector('[data-role="clear-month"]'),
  mask: document.querySelector('[data-role="dialog-mask"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogOk: document.querySelector('[data-role="dialog-ok"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]')
};

function pad2(n) {
  return String(n).padStart(2, "0");
}

function todayISO() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function currentMonth() {
  return todayISO().slice(0, 7);
}

function selectedType() {
  const checked = el.form.querySelector('input[name="type"]:checked');
  return checked && checked.value === "income" ? "income" : "expense";
}

function categoriesFor(type) {
  return type === "income" ? INCOME_CATEGORIES : EXPENSE_CATEGORIES;
}

function fillCategories(type, keepValue) {
  const list = categoriesFor(type);
  const prev = keepValue ? el.category.value : "";
  el.category.textContent = "";
  list.forEach(function (name) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    el.category.appendChild(opt);
  });
  if (prev && list.indexOf(prev) !== -1) {
    el.category.value = prev;
  }
}

function formatMoney(n) {
  const num = Number(n) || 0;
  const sign = num < 0 ? "-" : "";
  const abs = Math.abs(num);
  return sign + "¥" + abs.toFixed(2);
}

function formatDateText(iso) {
  if (typeof iso !== "string" || iso.length < 10) return iso || "";
  return iso.slice(0, 10);
}

function monthOf(iso) {
  return typeof iso === "string" ? iso.slice(0, 7) : "";
}

function showFormMsg(text, kind) {
  el.formMsg.textContent = text || "";
  el.formMsg.classList.remove("is-error", "is-ok");
  if (kind === "error") el.formMsg.classList.add("is-error");
  if (kind === "ok") el.formMsg.classList.add("is-ok");
}

function normalizeRecord(raw) {
  const rec = raw && typeof raw === "object" ? raw : {};
  const type = rec.type === "income" ? "income" : "expense";
  const amount = Number(rec.amount);
  return {
    id: typeof rec.id === "string" && rec.id ? rec.id : "r_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8),
    date: typeof rec.date === "string" ? rec.date.slice(0, 10) : todayISO(),
    type: type,
    category: typeof rec.category === "string" && rec.category ? rec.category : (type === "income" ? "其他收入" : "其他支出"),
    amount: isFinite(amount) ? amount : 0,
    note: typeof rec.note === "string" ? rec.note : "",
    createdAt: typeof rec.createdAt === "number" ? rec.createdAt : Date.now()
  };
}

function parseAmount(text) {
  const cleaned = String(text == null ? "" : text).trim().replace(/[¥￥,\s]/g, "");
  if (!cleaned) return { ok: false, reason: "请输入金额" };
  if (!/^\d+(\.\d{1,2})?$/.test(cleaned)) return { ok: false, reason: "金额格式不正确，请输入正数，最多两位小数" };
  const value = Number(cleaned);
  if (!isFinite(value) || value <= 0) return { ok: false, reason: "金额必须大于 0" };
  if (value > 999999999) return { ok: false, reason: "金额过大，请检查输入" };
  return { ok: true, value: Math.round(value * 100) / 100 };
}

function isValidISODate(text) {
  if (typeof text !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const parts = text.split("-");
  const y = Number(parts[0]);
  const m = Number(parts[1]);
  const d = Number(parts[2]);
  if (m < 1 || m > 12 || d < 1 || d > 31) return false;
  const dt = new Date(y, m - 1, d);
  return dt.getFullYear() === y && dt.getMonth() === m - 1 && dt.getDate() === d;
}

function visibleRecords() {
  const list = state.records.slice();
  const filtered = state.filterMonth
    ? list.filter(function (r) { return monthOf(r.date) === state.filterMonth; })
    : list;
  filtered.sort(function (a, b) {
    if (a.date === b.date) return (b.createdAt || 0) - (a.createdAt || 0);
    return a.date < b.date ? 1 : -1;
  });
  return filtered;
}

function renderSummary(list) {
  let income = 0;
  let expense = 0;
  list.forEach(function (r) {
    if (r.type === "income") income += r.amount;
    else expense += r.amount;
  });
  income = Math.round(income * 100) / 100;
  expense = Math.round(expense * 100) / 100;
  const balance = Math.round((income - expense) * 100) / 100;

  el.sumIncome.textContent = formatMoney(income);
  el.sumExpense.textContent = formatMoney(expense);
  el.sumBalance.textContent = formatMoney(balance);
  el.sumBalance.classList.toggle("expense", balance < 0);
}

function renderList() {
  const list = visibleRecords();
  el.list.textContent = "";

  if (list.length === 0) {
    const empty = document.createElement("li");
    empty.className = "empty";
    empty.textContent = state.records.length === 0
      ? "还没有任何记录，先在上方添加第一笔吧。"
      : "该月份没有记录，试试切换月份或选择“全部月份”。";
    el.list.appendChild(empty);
  } else {
    list.forEach(function (rec) {
      const li = document.createElement("li");
      li.className = "record-item";

      const main = document.createElement("div");
      main.className = "rec-main";

      const line1 = document.createElement("div");
      line1.className = "rec-line1";

      const dateSpan = document.createElement("span");
      dateSpan.className = "rec-date";
      dateSpan.textContent = formatDateText(rec.date);
      line1.appendChild(dateSpan);

      const tag = document.createElement("span");
      tag.className = "tag " + rec.type;
      tag.textContent = rec.type === "income" ? "收入" : "支出";
      line1.appendChild(tag);

      const cat = document.createElement("span");
      cat.className = "rec-category";
      cat.textContent = rec.category;
      line1.appendChild(cat);

      main.appendChild(line1);

      if (rec.note) {
        const note = document.createElement("div");
        note.className = "rec-note";
        note.textContent = rec.note;
        main.appendChild(note);
      }

      li.appendChild(main);

      const amount = document.createElement("span");
      amount.className = "rec-amount " + rec.type;
      amount.textContent = (rec.type === "income" ? "+" : "-") + formatMoney(rec.amount).replace("-", "");
      li.appendChild(amount);

      const del = document.createElement("button");
      del.type = "button";
      del.className = "rec-del";
      del.textContent = "删除";
      del.setAttribute("data-id", rec.id);
      del.setAttribute("aria-label", "删除记录 " + rec.category + " " + formatMoney(rec.amount));
      li.appendChild(del);

      el.list.appendChild(li);
    });
  }

  const scopeText = state.filterMonth ? state.filterMonth + " 月" : "全部月份";
  el.listHint.textContent = "共 " + list.length + " 条记录（" + scopeText + "）";
  renderSummary(list);
}

function renderAll() {
  renderList();
}

async function persist(nextRecords) {
  const prev = await appStore.getState();
  const base = prev && typeof prev === "object" ? prev : {};
  const next = Object.assign({}, base, { records: nextRecords });
  await appStore.setState(next);
}

async function addRecord(rec) {
  const nextRecords = state.records.concat([rec]);
  await persist(nextRecords);
  state.records = nextRecords;
  renderAll();
}

async function deleteRecord(id) {
  const nextRecords = state.records.filter(function (r) { return r.id !== id; });
  await persist(nextRecords);
  state.records = nextRecords;
  renderAll();
}

function openDialog(id) {
  const rec = state.records.filter(function (r) { return r.id === id; })[0];
  if (!rec) return;
  state.pendingDeleteId = id;
  el.dialogText.textContent = "确定要删除这条记录吗？\n" + formatDateText(rec.date) + " · " +
    (rec.type === "income" ? "收入" : "支出") + " · " + rec.category + " · " + formatMoney(rec.amount) +
    (rec.note ? " · " + rec.note : "") + "\n删除后无法恢复。";
  el.mask.hidden = false;
  el.dialogOk.focus();
}

function closeDialog() {
  state.pendingDeleteId = null;
  el.mask.hidden = true;
}

async function confirmDelete() {
  const id = state.pendingDeleteId;
  if (!id) {
    closeDialog();
    return;
  }
  el.dialogOk.disabled = true;
  try {
    await deleteRecord(id);
    closeDialog();
    showFormMsg("已删除该条记录。", "ok");
  } catch (err) {
    el.dialogOk.disabled = false;
    el.dialogText.textContent = "删除失败：" + (err && err.message ? err.message : "保存出错，请重试。");
    return;
  }
  el.dialogOk.disabled = false;
}

function resetForm() {
  el.date.value = todayISO();
  const expenseRadio = el.form.querySelector('input[name="type"][value="expense"]');
  if (expenseRadio) expenseRadio.checked = true;
  fillCategories("expense", false);
  el.amount.value = "";
  el.note.value = "";
  showFormMsg("", "");
}

async function onSubmit(event) {
  event.preventDefault();
  if (state.saving) return;

  const date = el.date.value;
  if (!isValidISODate(date)) {
    showFormMsg("请选择有效的日期。", "error");
    el.date.focus();
    return;
  }

  const parsed = parseAmount(el.amount.value);
  if (!parsed.ok) {
    showFormMsg(parsed.reason, "error");
    el.amount.focus();
    return;
  }

  const type = selectedType();
  const category = el.category.value || (type === "income" ? "其他收入" : "其他支出");
  const note = el.note.value.trim().slice(0, 60);

  const rec = normalizeRecord({
    id: "r_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8),
    date: date,
    type: type,
    category: category,
    amount: parsed.value,
    note: note,
    createdAt: Date.now()
  });

  state.saving = true;
  const submitBtn = el.form.querySelector('button[type="submit"]');
  if (submitBtn) submitBtn.disabled = true;
  try {
    await addRecord(rec);
    showFormMsg("已添加：" + formatDateText(rec.date) + " " + (rec.type === "income" ? "收入" : "支出") + " " + formatMoney(rec.amount), "ok");
    el.amount.value = "";
    el.note.value = "";
    el.amount.focus();
  } catch (err) {
    showFormMsg("保存失败：" + (err && err.message ? err.message : "请重试。") + "（输入内容已保留）", "error");
  } finally {
    state.saving = false;
    if (submitBtn) submitBtn.disabled = false;
  }
}

function onListClick(event) {
  const target = event.target;
  if (!target || !target.getAttribute) return;
  const id = target.getAttribute("data-id");
  if (target.classList && target.classList.contains("rec-del") && id) {
    openDialog(id);
  }
}

function onMonthChange() {
  state.filterMonth = el.month.value || "";
  renderAll();
}

function onClearMonth() {
  el.month.value = "";
  state.filterMonth = "";
  renderAll();
}

function onTypeChange() {
  fillCategories(selectedType(), false);
}

function onMaskClick(event) {
  if (event.target === el.mask) closeDialog();
}

function onKeyDown(event) {
  if (event.key === "Escape" && !el.mask.hidden) closeDialog();
}

async function init() {
  el.date.value = todayISO();
  fillCategories("expense", false);
  el.month.value = "";

  let raw = null;
  try {
    raw = await appStore.getState();
  } catch (err) {
    raw = null;
  }

  const base = raw && typeof raw === "object" ? raw : {};
  const hasRecords = Array.isArray(base.records);
  const source = hasRecords ? base.records : [];
  state.records = source.map(normalizeRecord);

  if (!hasRecords) {
    try {
      await persist(state.records);
    } catch (err) {
      showFormMsg("初始化存储失败：" + (err && err.message ? err.message : "请刷新重试。"), "error");
    }
  }

  el.form.addEventListener("submit", onSubmit);
  el.form.addEventListener("change", function (event) {
    if (event.target && event.target.name === "type") onTypeChange();
  });
  el.resetBtn.addEventListener("click", resetForm);
  el.month.addEventListener("change", onMonthChange);
  el.clearMonthBtn.addEventListener("click", onClearMonth);
  el.list.addEventListener("click", onListClick);
  el.dialogOk.addEventListener("click", confirmDelete);
  el.dialogCancel.addEventListener("click", closeDialog);
  el.mask.addEventListener("click", onMaskClick);
  document.addEventListener("keydown", onKeyDown);

  renderAll();
}

await init();

artifact.css:
:root {
  --bg: #f4f6fb;
  --card: #ffffff;
  --text: #1f2937;
  --muted: #6b7280;
  --line: #e5e7eb;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --income: #0f9d58;
  --expense: #dc2626;
  --danger: #dc2626;
  --radius: 12px;
}

* { box-sizing: border-box; }

.app {
  max-width: 860px;
  margin: 0 auto;
  padding: 20px 16px 48px;
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
}

.topbar { margin-bottom: 16px; }

.topbar h1 {
  margin: 0 0 4px;
  font-size: 22px;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 16px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.card h2 {
  margin: 0 0 12px;
  font-size: 16px;
}

.entry-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 14px;
}

.field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.field-wide { grid-column: 1 / -1; }

.field label,
.field-label {
  font-size: 13px;
  color: var(--muted);
  font-weight: 600;
}

input[type="date"],
input[type="month"],
input[type="text"],
select {
  width: 100%;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
}

input:focus,
select:focus {
  outline: 2px solid rgba(37, 99, 235, 0.35);
  outline-offset: 1px;
  border-color: var(--primary);
}

.radio-row { display: flex; gap: 8px; }

.radio-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  cursor: pointer;
  font-size: 14px;
  user-select: none;
}

.radio-chip input { accent-color: var(--primary); }

.radio-chip:has(input:checked) {
  border-color: var(--primary);
  background: rgba(37, 99, 235, 0.08);
  color: var(--primary-dark);
  font-weight: 600;
}

.form-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 9px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); }

.btn-ghost {
  background: #fff;
  border-color: var(--line);
  color: var(--text);
}
.btn-ghost:hover { background: #f3f4f6; }

.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover { background: #b91c1c; }

.btn-sm { padding: 7px 12px; font-size: 13px; }

.form-msg {
  grid-column: 1 / -1;
  margin: 0;
  min-height: 20px;
  font-size: 13px;
  color: var(--muted);
}

.form-msg.is-error { color: var(--danger); font-weight: 600; }
.form-msg.is-ok { color: var(--income); font-weight: 600; }

.list-head {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.list-head h2 { margin: 0; }

.filter-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.filter-row label { font-size: 13px; color: var(--muted); font-weight: 600; }
.filter-row input[type="month"] { width: auto; }

.summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 12px;
  background: #f8fafc;
  border: 1px solid var(--line);
  border-radius: 10px;
  margin-bottom: 12px;
}

.sum-item { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.sum-label { font-size: 12px; color: var(--muted); }
.sum-value { font-size: 17px; font-weight: 700; word-break: break-all; }
.sum-value.income { color: var(--income); }
.sum-value.expense { color: var(--expense); }
.sum-value.balance { color: var(--primary-dark); }

.list-hint {
  margin: 0 0 10px;
  font-size: 13px;
  color: var(--muted);
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.record-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
}

.rec-main { flex: 1 1 auto; min-width: 0; }

.rec-line1 {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.rec-date { font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }

.tag {
  font-size: 12px;
  padding: 1px 8px;
  border-radius: 999px;
  border: 1px solid currentColor;
}

.tag.income { color: var(--income); }
.tag.expense { color: var(--expense); }

.rec-category { font-weight: 600; font-size: 14px; }

.rec-note {
  margin-top: 2px;
  font-size: 13px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.rec-amount {
  font-size: 16px;
  font-weight: 700;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.rec-amount.income { color: var(--income); }
.rec-amount.expense { color: var(--expense); }

.rec-del {
  border: 1px solid var(--line);
  background: #fff;
  color: var(--danger);
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 13px;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
}

.rec-del:hover { background: #fef2f2; border-color: #fecaca; }

.empty {
  padding: 24px 12px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
  border: 1px dashed var(--line);
  border-radius: 10px;
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
}

.dialog-mask[hidden] { display: none; }

.dialog {
  background: #fff;
  border-radius: var(--radius);
  padding: 18px;
  width: 100%;
  max-width: 380px;
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.25);
}

.dialog h3 { margin: 0 0 8px; font-size: 16px; }

.dialog-text {
  margin: 0 0 16px;
  font-size: 14px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; }

@media (max-width: 560px) {
  .entry-form { grid-template-columns: minmax(0, 1fr); }
  .summary { grid-template-columns: minmax(0, 1fr); }
  .record-item { flex-wrap: wrap; }
  .rec-amount { margin-left: auto; }
}
